// that represents their union, otherwise return both as separate polygons

// Check if polygons overlap using bounding box intersection
cg3::BoundingBox2 bb1 = P1.boundingBox();
cg3::BoundingBox2 bb2 = P2.boundingBox();

if (!bb1.intersects(bb2)) {
    // No overlap, return both polygons as separate
    result.push_back(PolygonWithHoles2d(P1));
    result.push_back(PolygonWithHoles2d(P2));
